import React, { useState, useEffect, useRef } from "react";
import { supabase } from "./supabaseClient.js";

const LOGO_SRC = "data:image/png;base64,";

const COMPANY = {
  name: "Genesis Incorporated Ltd",
  footer:
    "Genesis Incorporated Ltd, Registered Office: PO Box 3653, Wokingham, RG40 9NN   |   Office Tel: 0333 900 7247   |   24 Hour Mobile: 07769278359   |   VAT No 389323756   |   Company Registration No: 13398244",
  bankName: "Starling Bank Ltd",
  bankAccount: "33191563",
  bankSortCode: "60-83-71",
  invoicePrefix: "GI/",
};

const SALES_PEOPLE = ["MARC", "TOM", "OFFICE"];

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function formatMoney(n) {
  const num = Number(n) || 0;
  return num.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function todayLong(d) {
  const date = d ? new Date(d) : new Date();
  const day = date.getDate();
  const suffix =
    day % 10 === 1 && day !== 11
      ? "st"
      : day % 10 === 2 && day !== 12
      ? "nd"
      : day % 10 === 3 && day !== 13
      ? "rd"
      : "th";
  const month = date.toLocaleString("en-GB", { month: "long" });
  return `${day}${suffix} ${month} ${date.getFullYear()}`;
}

function todayISO() {
  const d = new Date();
  return d.toISOString().slice(0, 10);
}

function blankInvoice(nextNumber) {
  return {
    id: uid(),
    invoiceNumber: nextNumber,
    invoiceDate: todayISO(),
    toName: "",
    toCompany: "",
    toEmail: "",
    salesPerson: "MARC",
    jobNo: "",
    quoteNo: "",
    dueDate: "UPON RECEIPT, THANK YOU",
    siteAddressLine1: "",
    siteAddressLine2: "",
    sitePostcode: "",
    descriptionHeading: "",
    descriptionBody: "",
    lineItems: [{ id: uid(), label: "", amount: "" }],
    vatRate: 20,
    status: "draft",
    createdAt: new Date().toISOString(),
    xeroStatus: "not_sent",
  };
}

function nextInvoiceNumber(savedInvoices) {
  let max = 2630;
  savedInvoices.forEach((inv) => {
    const m = String(inv.invoiceNumber || "").match(/(\d+)/);
    if (m) {
      const n = parseInt(m[1], 10);
      if (n > max) max = n;
    }
  });
  return String(max + 1);
}

async function fetchInvoices() {
  const { data, error } = await supabase
    .from("invoices")
    .select("id, invoice_number, data, updated_at")
    .order("updated_at", { ascending: false });
  if (error) {
    console.error(error);
    return [];
  }
  // Each row's `data` holds the full invoice object; row id is the source of truth.
  return data.map((row) => ({ ...row.data, id: row.id }));
}

async function upsertInvoice(inv) {
  const { error } = await supabase.from("invoices").upsert(
    {
      id: inv.id,
      invoice_number: String(inv.invoiceNumber || ""),
      data: inv,
      updated_at: new Date().toISOString(),
    },
    { onConflict: "id" }
  );
  return !error;
}

async function deleteInvoiceRow(id) {
  const { error } = await supabase.from("invoices").delete().eq("id", id);
  return !error;
}

export default function InvoiceApp({ session }) {
  const [invoices, setInvoices] = useState([]);
  const [current, setCurrent] = useState(null);
  const [view, setView] = useState("list"); // list | edit | preview
  const [loading, setLoading] = useState(true);
  const [saveState, setSaveState] = useState("idle"); // idle | saving | saved
  const [toast, setToast] = useState("");
  const printRef = useRef(null);

  useEffect(() => {
    (async () => {
      const saved = await fetchInvoices();
      setInvoices(saved);
      setLoading(false);
    })();
  }, []);

  const showToast = (msg) => {
    setToast(msg);
    setTimeout(() => setToast(""), 2500);
  };

  const startNew = () => {
    const num = nextInvoiceNumber(invoices);
    setCurrent(blankInvoice(num));
    setView("edit");
  };

  const editExisting = (inv) => {
    setCurrent(JSON.parse(JSON.stringify(inv)));
    setView("edit");
  };

  const duplicateExisting = (inv) => {
    const num = nextInvoiceNumber(invoices);
    const copy = JSON.parse(JSON.stringify(inv));
    copy.id = uid();
    copy.invoiceNumber = num;
    copy.invoiceDate = todayISO();
    copy.status = "draft";
    copy.xeroStatus = "not_sent";
    setCurrent(copy);
    setView("edit");
  };

  const saveInvoice = async () => {
    setSaveState("saving");
    const ok = await upsertInvoice(current);
    if (!ok) {
      setSaveState("idle");
      showToast("Save failed — check your connection");
      return;
    }
    const exists = invoices.some((i) => i.id === current.id);
    const list = exists
      ? invoices.map((i) => (i.id === current.id ? current : i))
      : [current, ...invoices];
    setInvoices(list);
    setSaveState("saved");
    setTimeout(() => setSaveState("idle"), 1200);
    showToast("Invoice saved");
    setView("list");
  };

  const deleteInvoice = async (id) => {
    if (!window.confirm("Delete this invoice? This cannot be undone.")) return;
    const ok = await deleteInvoiceRow(id);
    if (!ok) {
      showToast("Delete failed — check your connection");
      return;
    }
    const list = invoices.filter((i) => i.id !== id);
    setInvoices(list);
    showToast("Invoice deleted");
  };

  const netTotal = (inv) =>
    (inv?.lineItems || []).reduce((sum, li) => sum + (Number(li.amount) || 0), 0);
  const vatAmount = (inv) => (netTotal(inv) * (Number(inv?.vatRate) || 0)) / 100;
  const grandTotal = (inv) => netTotal(inv) + vatAmount(inv);

  const updateField = (field, value) => setCurrent((c) => ({ ...c, [field]: value }));

  const updateLineItem = (id, field, value) =>
    setCurrent((c) => ({
      ...c,
      lineItems: c.lineItems.map((li) => (li.id === id ? { ...li, [field]: value } : li)),
    }));

  const addLineItem = () =>
    setCurrent((c) => ({
      ...c,
      lineItems: [...c.lineItems, { id: uid(), label: "", amount: "" }],
    }));

  const removeLineItem = (id) =>
    setCurrent((c) => ({
      ...c,
      lineItems: c.lineItems.length > 1 ? c.lineItems.filter((li) => li.id !== id) : c.lineItems,
    }));

  const handlePrint = (inv) => {
    const target = inv || current;
    setCurrent(target);
    setView("preview");
    const prevTitle = document.title;
    document.title = `Invoice GI-${target.invoiceNumber}`;
    setTimeout(() => {
      window.print();
      setTimeout(() => (document.title = prevTitle), 500);
    }, 250);
  };

  const openPreview = (inv) => {
    setCurrent(JSON.parse(JSON.stringify(inv)));
    setView("preview");
  };

  if (loading) {
    return (
      <div style={styles.loadingWrap}>
        <div style={styles.spinner} />
        <div style={{ color: "#6b7280", fontSize: 14 }}>Loading invoices…</div>
      </div>
    );
  }

  return (
    <div style={styles.app}>
      <style>{PRINT_CSS}</style>
      {view !== "preview" && (
        <TopBar
          view={view}
          onList={() => setView("list")}
          saveState={saveState}
          userEmail={session?.user?.email}
        />
      )}

      {view === "list" && (
        <InvoiceList
          invoices={invoices}
          onNew={startNew}
          onEdit={editExisting}
          onDuplicate={duplicateExisting}
          onDelete={deleteInvoice}
          onOpenPdf={(inv) => handlePrint(inv)}
          netTotal={netTotal}
          grandTotal={grandTotal}
        />
      )}

      {view === "edit" && current && (
        <InvoiceEditor
          inv={current}
          updateField={updateField}
          updateLineItem={updateLineItem}
          addLineItem={addLineItem}
          removeLineItem={removeLineItem}
          netTotal={netTotal(current)}
          vatAmount={vatAmount(current)}
          grandTotal={grandTotal(current)}
          onSave={saveInvoice}
          onCancel={() => setView("list")}
          onPreview={() => setView("preview")}
        />
      )}

      {view === "preview" && current && (
        <PreviewScreen
          inv={current}
          netTotal={netTotal(current)}
          vatAmount={vatAmount(current)}
          grandTotal={grandTotal(current)}
          onBack={() => setView("edit")}
          onPrint={() => handlePrint(current)}
          printRef={printRef}
        />
      )}

      {toast && <div style={styles.toast}>{toast}</div>}
    </div>
  );
}

function TopBar({ view, onList, saveState, userEmail }) {
  return (
    <div style={styles.topbar} className="no-print">
      <div style={styles.brandRow}>
        <img src={LOGO_SRC} alt="Genesis Incorporated" style={{ height: 30 }} />
        <div style={{ fontSize: 13, color: "#5b6472", fontWeight: 600, letterSpacing: 0.3 }}>
          Sales Invoices
        </div>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
        {saveState === "saving" && <span style={styles.saveTag}>Saving…</span>}
        {saveState === "saved" && <span style={{ ...styles.saveTag, color: "#16794f" }}>Saved</span>}
        {view !== "list" && (
          <button style={styles.ghostBtn} onClick={onList}>
            ← All invoices
          </button>
        )}
        {userEmail && <span style={styles.userTag}>{userEmail}</span>}
        <button style={styles.ghostBtn} onClick={() => supabase.auth.signOut()}>
          Sign out
        </button>
      </div>
    </div>
  );
}

function InvoiceList({ invoices, onNew, onEdit, onDuplicate, onDelete, onOpenPdf, netTotal, grandTotal }) {
  const [query, setQuery] = useState("");
  const norm = (s) => (s || "").toString().toLowerCase().replace(/^gi[/]?/i, "").trim();
  const filtered = invoices.filter((i) => {
    const q = norm(query);
    if (!q) return true;
    return (
      norm(i.invoiceNumber).includes(q) ||
      (i.toName || "").toLowerCase().includes(query.toLowerCase()) ||
      (i.toCompany || "").toLowerCase().includes(query.toLowerCase()) ||
      (i.siteAddressLine1 || "").toLowerCase().includes(query.toLowerCase())
    );
  });
  const exactNumberMatch = invoices.find(
    (i) => norm(i.invoiceNumber) === norm(query) && norm(query) !== ""
  );

  return (
    <div style={styles.listWrap}>
      <div style={styles.listHeaderRow}>
        <div>
          <h1 style={styles.h1}>Invoices</h1>
          <div style={{ color: "#6b7280", fontSize: 13.5 }}>
            {invoices.length} invoice{invoices.length === 1 ? "" : "s"} on file
          </div>
        </div>
        <button style={styles.primaryBtn} onClick={onNew}>
          + New invoice
        </button>
      </div>

      <div style={{ position: "relative", marginBottom: 16 }}>
        <input
          style={styles.searchInput}
          placeholder="Search by invoice number (e.g. 2631), customer, or site address…"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && exactNumberMatch) onEdit(exactNumberMatch);
          }}
        />
        {exactNumberMatch && (
          <div style={styles.jumpHint}>
            Press Enter to open GI/{exactNumberMatch.invoiceNumber}
          </div>
        )}
      </div>

      {filtered.length === 0 && (
        <div style={styles.emptyState}>
          <div style={{ fontSize: 15, color: "#374151", marginBottom: 6, fontWeight: 600 }}>
            {invoices.length === 0 ? "No invoices yet" : "No matches"}
          </div>
          <div style={{ color: "#9ca3af", fontSize: 13.5 }}>
            {invoices.length === 0
              ? "Create your first invoice to get started."
              : "Try a different search."}
          </div>
        </div>
      )}

      <div style={styles.tableWrap}>
        {filtered.map((inv) => (
          <div key={inv.id} style={styles.row}>
            <div style={{ minWidth: 90, fontWeight: 700, color: "#1f2a44" }}>
              GI/{inv.invoiceNumber}
            </div>
            <div style={{ flex: 1, minWidth: 160 }}>
              <div style={{ fontWeight: 600, color: "#1f2a44", fontSize: 14 }}>
                {inv.toCompany || inv.toName || "—"}
              </div>
              <div style={{ color: "#8a93a3", fontSize: 12.5 }}>
                {inv.siteAddressLine1 || "No site address"}
              </div>
            </div>
            <div style={{ width: 110, color: "#5b6472", fontSize: 13 }}>
              {todayLong(inv.invoiceDate)}
            </div>
            <div style={{ width: 100, textAlign: "right", fontWeight: 700, color: "#1f2a44" }}>
              £{formatMoney(grandTotal(inv))}
            </div>
            <div style={{ width: 92 }}>
              <span
                style={{
                  ...styles.statusPill,
                  ...(inv.xeroStatus === "sent" ? styles.pillGreen : styles.pillGrey),
                }}
              >
                {inv.xeroStatus === "sent" ? "In Xero" : "Not sent"}
              </span>
            </div>
            <div style={{ display: "flex", gap: 6 }}>
              <button style={styles.smallBtn} onClick={() => onEdit(inv)}>
                Edit
              </button>
              <button style={styles.smallBtnAccent} onClick={() => onOpenPdf(inv)}>
                PDF
              </button>
              <button style={styles.smallBtn} onClick={() => onDuplicate(inv)}>
                Duplicate
              </button>
              <button style={styles.smallBtnDanger} onClick={() => onDelete(inv.id)}>
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function Field({ label, children, width }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 5, width: width || "100%" }}>
      <label style={styles.label}>{label}</label>
      {children}
    </div>
  );
}

